import type { LonLat } from './coords'
import { CountryIndex, type CountryCollection, type CountryFeature } from './countries'
import {
  difficultyScore,
  difficultyTiers,
  familiarityScore,
  type DifficultyTier,
} from './difficulty'
import { NameMatcher } from './names'

export interface Capital {
  name: string
  at: LonLat
}

/** Per-country facts generated by scripts/build-countries.mjs, for playable places only. */
export interface CountryFacts {
  iso2: string
  /** UN subregion, e.g. "Western Africa". */
  subregion: string
  population: number
  /** GDP in millions of US dollars; negative when unknown. */
  gdpMd: number
  /** Natural Earth label rank: 2 is the most prominent, 6 the least. */
  labelRank: number
  areaKm2: number
  /** A point inside the country, for markers and bearings. */
  label: LonLat
  landNorth: boolean
  landSouth: boolean
  onEquator: boolean
  /** Playable countries sharing a land border. */
  neighbors: string[]
  /** The first is the main capital; every one counts as a hit. */
  capitals: Capital[]
  landlocked: boolean
  island: boolean
  coasts: string[]
  /** Debatable coasts (marginal seas) that are accepted as answers but never required. */
  coastsLenient: string[]
  familiarityAdjust: number
  aliases: string[]
}

export interface FactsFile {
  countries: Record<string, CountryFacts>
  /** Border-to-border km between playable countries: upper triangle, row-major, ids sorted. */
  distances: { ids: string[]; km: number[] }
  /** Land borders that World Journey does not let you cross (overseas departments). */
  journeyExclusions: [string, string][]
  ambiguousNames: Record<string, string[]>
}

/**
 * Everything the game rules know about the world: shapes for hit-testing plus facts, distances,
 * name matching and difficulty. Built once at load and shared by every mode (and, later, by the
 * multiplayer server), so it must not depend on the browser.
 */
export class GeoData {
  readonly countries: CountryIndex
  readonly names: NameMatcher
  /** Playable country ids, sorted. */
  readonly playableIds: string[]
  readonly journeyExclusions: [string, string][]
  private readonly facts: Record<string, CountryFacts>
  private readonly distanceRow: Map<string, number>
  private readonly distanceKm: number[]
  private readonly familiarityById: Map<string, number>
  private readonly difficultyById: Map<string, number>
  private readonly tierById: Map<string, DifficultyTier>

  constructor(countries: CountryIndex, file: FactsFile) {
    this.countries = countries
    this.facts = file.countries
    this.playableIds = [...file.distances.ids]
    this.journeyExclusions = file.journeyExclusions
    this.distanceRow = new Map(file.distances.ids.map((id, index) => [id, index]))
    this.distanceKm = file.distances.km

    this.familiarityById = new Map(
      this.playableIds.map((id) => [id, familiarityScore(this.factsOf(id))]),
    )
    this.difficultyById = new Map(
      this.playableIds.map((id) => [
        id,
        difficultyScore(this.familiarityById.get(id)!, this.factsOf(id).areaKm2),
      ]),
    )
    this.tierById = difficultyTiers(this.difficultyById)
    this.names = new NameMatcher(
      this.playableIds.map((id) => ({
        id,
        name: this.nameOf(id),
        aliases: this.factsOf(id).aliases,
      })),
      file.ambiguousNames,
    )
  }

  feature(id: string): CountryFeature {
    const feature = this.countries.get(id)
    if (!feature) throw new Error(`Unknown country: ${id}`)
    return feature
  }

  factsOf(id: string): CountryFacts {
    const facts = this.facts[id]
    if (!facts) throw new Error(`No facts for country: ${id}`)
    return facts
  }

  nameOf(id: string): string {
    return this.countries.get(id)?.properties.name ?? id
  }

  /** Shortest distance between the two countries' borders (0 for neighbours). */
  borderDistanceKm(a: string, b: string): number {
    if (a === b) return 0
    let i = this.distanceRow.get(a)
    let j = this.distanceRow.get(b)
    if (i === undefined || j === undefined) throw new Error(`No distance for ${a}–${b}`)
    if (i > j) [i, j] = [j, i]
    const n = this.playableIds.length
    return this.distanceKm[i * n - (i * (i + 1)) / 2 + (j - i - 1)]
  }

  familiarity(id: string): number {
    return this.familiarityById.get(id) ?? 0
  }

  /** 0 (easy to find) … 1 (hard). */
  difficulty(id: string): number {
    return this.difficultyById.get(id) ?? 1
  }

  difficultyTier(id: string): DifficultyTier {
    return this.tierById.get(id) ?? 5
  }
}

export async function loadGeoData(): Promise<GeoData> {
  const [collection, facts] = await Promise.all([
    fetchJson<CountryCollection>('data/countries.json'),
    fetchJson<FactsFile>('data/facts.json'),
  ])
  return new GeoData(new CountryIndex(collection), facts)
}

async function fetchJson<T>(path: string): Promise<T> {
  const version = import.meta.env.VITE_ASSET_VERSION ?? 'dev'
  const response = await fetch(`${import.meta.env.BASE_URL}${path}?v=${version}`)
  if (!response.ok) throw new Error(`Failed to load ${path}: ${response.status}`)
  return (await response.json()) as T
}
